// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createOwner, createPet, createVisit, updateVisit, getVisit, deleteOwner } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    // Request Body
    const ownersPostRequestBody: string = `{
        "address": "1 Test St.",
        "city": "Madison",
        "firstName": "Skyramp",
        "lastName": "Duration",
        "telephone": "6085550001"
    }`;

    const ownersPostResponse = await createOwner(client, URL_localhost, ownersPostRequestBody);

    try {
        expect(ownersPostResponse.statusCode, 'status code').toBe(201);

        expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Skyramp");
        expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Duration");
        expect(getResponseValue(ownersPostResponse, "address"), 'address').toBe("1 Test St.");
        expect(getResponseValue(ownersPostResponse, "city"), 'city').toBe("Madison");
        expect(getResponseValue(ownersPostResponse, "telephone"), 'telephone').toBe("6085550001");
        expect(getResponseValue(ownersPostResponse, "id"), 'id').toBeGreaterThan(0);

        // Request Body
        const petsPostRequestBody: string = `{
            "birthDate": "2020-01-01",
            "name": "Duration",
            "type": {
                "id": 1,
                "name": "cat"
            }
        }`;

        const petsPostResponse = await createPet(
            client,
            URL_localhost,
            getResponseValue(ownersPostResponse, "id"),
            petsPostRequestBody
        );
        expect(petsPostResponse.statusCode, 'status code').toBe(201);

        expect(getResponseValue(petsPostResponse, "name"), 'name').toBe("Duration");
        expect(getResponseValue(petsPostResponse, "birthDate"), 'birthDate').toBe("2020-01-01");
        expect(getResponseValue(petsPostResponse, "type.name"), 'type.name').toBe("cat");
        expect(getResponseValue(petsPostResponse, "ownerId"), 'ownerId').toBe(getResponseValue(ownersPostResponse, "id"));
        expect(getResponseValue(petsPostResponse, "id"), 'id').toBeGreaterThan(0);

        // Request Body
        const visitsPostRequestBody: string = `{
            "date": "2026-03-01",
            "description": "sixty minute booking",
            "durationMinutes": 60
        }`;

        const visitsPostResponse = await createVisit(
            client,
            URL_localhost,
            getResponseValue(ownersPostResponse, "id"),
            getResponseValue(petsPostResponse, "id"),
            visitsPostRequestBody
        );
        expect(visitsPostResponse.statusCode, 'status code').toBe(201);

        expect(getResponseValue(visitsPostResponse, "date"), 'date').toBe("2026-03-01");
        expect(getResponseValue(visitsPostResponse, "description"), 'description').toBe("sixty minute booking");
        expect(getResponseValue(visitsPostResponse, "durationMinutes"), 'durationMinutes').toBe(60);
        expect(getResponseValue(visitsPostResponse, "petId"), 'petId').toBe(getResponseValue(petsPostResponse, "id"));
        expect(getResponseValue(visitsPostResponse, "id"), 'id').toBeGreaterThan(0);

        // Request Body
        const visitsVisitsPutRequestBody: string = `{
            "date": "2026-03-01",
            "description": "sixty minute booking, renamed"
        }`;

        const visitsVisitsPutResponse = await updateVisit(
            client,
            URL_localhost,
            getResponseValue(visitsPostResponse, "id"),
            visitsVisitsPutRequestBody
        );
        expect(visitsVisitsPutResponse.statusCode, 'status code').toBe(204);

        const visitsVisitsGetResponse = await getVisit(
            client,
            URL_localhost,
            getResponseValue(visitsPostResponse, "id")
        );

        expect(visitsVisitsGetResponse.statusCode, 'status code').toBe(200);

        // The PUT above did not mention durationMinutes, so the booked length must be untouched.
        expect(getResponseValue(visitsVisitsGetResponse, "durationMinutes"), 'durationMinutes').toBe(60);
        expect(getResponseValue(visitsVisitsGetResponse, "description"), 'description').toBe("sixty minute booking, renamed");
        expect(getResponseValue(visitsVisitsGetResponse, "date"), 'date').toBe("2026-03-01");
        expect(getResponseValue(visitsVisitsGetResponse, "id"), 'id').toBe(getResponseValue(visitsPostResponse, "id"));
        expect(getResponseValue(visitsVisitsGetResponse, "petId"), 'petId').toBe(getResponseValue(petsPostResponse, "id"));
    } finally {
        const ownersOwnersDeleteResponse = await deleteOwner(
            client,
            URL_localhost,
            getResponseValue(ownersPostResponse, "id")
        );

        expect(ownersOwnersDeleteResponse.statusCode, 'status code').toBe(204);
    }
});
